  1→//! Run command implementation.
  2→//!
  3→//! The `bivvy run` command executes setup workflows.
  4→
  5→use std::collections::{HashMap, HashSet};
  6→use std::path::{Path, PathBuf};
  7→
  8→use crate::cli::args::RunArgs;
  9→use crate::config::{evaluate_vars, load_merged_config, ConfigPaths, InterpolationContext};
 10→use crate::environment::resolver::ResolvedEnvironment;
 11→use crate::error::{BivvyError, Result};
 12→use crate::registry::Registry;
 13→use crate::requirements::checker::GapChecker;
 14→use crate::requirements::probe::EnvironmentProbe;
 15→use crate::requirements::registry::RequirementRegistry;
 16→use crate::runner::{RunOptions, SkipBehavior, WorkflowRunner};
 17→use crate::state::{ProjectId, RunHistoryBuilder, StateStore};
 18→use crate::steps::ResolvedStep;
 19→use crate::ui::{hints, OutputMode, RunSummary, StatusKind, StepSummary, UserInterface};
 20→
 21→use super::dispatcher::{Command, CommandResult};
 22→
 23→/// The run command implementation.
 24→pub struct RunCommand {
 25→    project_root: PathBuf,
 26→    args: RunArgs,
 27→}
 28→
 29→impl RunCommand {
 30→    /// Create a new run command.
 31→    pub fn new(project_root: &Path, args: RunArgs) -> Self {
 32→        Self {
 33→            project_root: project_root.to_path_buf(),
 34→            args,
 35→        }
 36→    }
 37→
 38→    /// Get the project root path.
 39→    pub fn project_root(&self) -> &Path {
 40→        &self.project_root
 41→    }
 42→
 43→    /// Get the command arguments.
 44→    pub fn args(&self) -> &RunArgs {
 45→        &self.args
 46→    }
 47→
 48→    /// Build run options from args.
 49→    fn build_options(&self) -> RunOptions {
 50→        let skip_behavior = match self.args.skip_behavior.as_str() {
 51→            "skip_only" => SkipBehavior::SkipOnly,
 52→            "run_anyway" => SkipBehavior::RunAnyway,
 53→            _ => SkipBehavior::SkipWithDependents,
 54→        };
 55→
 56→        RunOptions {
 57→            workflow: Some(self.args.workflow.clone()),
 58→            only: self.args.only.iter().cloned().collect(),
 59→            skip: self.args.skip.iter().cloned().collect(),
 60→            skip_behavior,
 61→            force: self.args.force.iter().cloned().collect(),
 62→            dry_run: self.args.dry_run,
 63→            provided_requirements: HashSet::new(),
 64→            active_environment: None,
 65→        }
 66→    }
 67→
 68→    /// Resolve the target environment using the priority chain.
 69→    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
 70→        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
 71→    }
 72→
 73→    /// Resolve steps from configuration.
 74→    ///
 75→    /// Steps with a `template` field are resolved through the Registry,
 76→    /// which merges template defaults with config overrides. Steps without
 77→    /// a template are treated as inline definitions.
 78→    fn resolve_steps(
 79→        &self,
 80→        config: &crate::config::BivvyConfig,
 81→        environment: Option<&str>,
 82→    ) -> Result<HashMap<String, ResolvedStep>> {
 83→        let registry = if config.template_sources.is_empty() {
 84→            Registry::new(Some(&self.project_root))?
 85→        } else {
 86→            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
 87→        };
 88→
 89→        let mut steps = HashMap::new();
 90→        for (name, step_config) in &config.steps {
 91→            let resolved = if let Some(template_name) = &step_config.template {
 92→                let (template, _source) = registry.resolve(template_name)?;
 93→                ResolvedStep::from_template(
 94→                    name,
 95→                    template,
 96→                    step_config,
 97→                    &step_config.inputs,
 98→                    environment,
 99→                )
100→            } else {
101→                ResolvedStep::from_config(name, step_config, environment)
102→            };
103→            steps.insert(name.clone(), resolved);
104→        }
105→        Ok(steps)
106→    }
107→}
108→
109→impl Command for RunCommand {
110→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
111→        // Load configuration
112→        let config = match load_merged_config(&self.project_root) {
113→            Ok(c) => c,
114→            Err(BivvyError::ConfigNotFound { .. }) => {
115→                ui.error("No configuration found. Run 'bivvy init' first.");
116→                return Ok(CommandResult::failure(2));
117→            }
118→            Err(e) => return Err(e),
119→        };
120→
121→        // Deprecation warning for --ci flag
122→        if self.args.ci {
123→            ui.warning(
124→                "--ci is deprecated and will be removed in 2.0. \
125→                 Use --non-interactive and --env ci instead.",
126→            );
127→        }
128→
129→        // Apply config default_output when no CLI flag was explicitly set.
130→        // OutputMode::Normal means the user didn't pass --verbose or --quiet.
131→        if ui.output_mode() == OutputMode::Normal {
132→            ui.set_output_mode(config.settings.default_output.into());
133→        }
134→
135→        // Resolve environment (before header so we can use resolved workflow)
136→        let resolved_env = self.resolve_environment(&config);
137→        let env_name = resolved_env.name.clone();
138→
139→        // Warn if the environment is not known
140→        if !resolved_env.is_known(&config) {
141→            ui.warning(&format!(
142→                "Unknown environment '{}'. It is not defined in settings.environments                  or a built-in. Step overrides for this environment will have no effect.",
143→                env_name
144→            ));
145→        }
146→
147→        // Get provided_requirements from environment config
148→        let provided_requirements: HashSet<String> = config
149→            .settings
150→            .environments

  1→//! Shell command execution.
  2→
  3→use crate::error::{BivvyError, Result};
  4→use std::collections::HashMap;
  5→use std::io::{BufRead, BufReader};
  6→use std::path::Path;
  7→use std::process::{Command, Stdio};
  8→use std::sync::mpsc;
  9→use std::thread;
 10→use std::time::{Duration, Instant};
 11→
 12→/// Result of executing a shell command.
 13→#[derive(Debug, Clone)]
 14→pub struct CommandResult {
 15→    /// Exit code (None if killed by signal).
 16→    pub exit_code: Option<i32>,
 17→
 18→    /// Standard output.
 19→    pub stdout: String,
 20→
 21→    /// Standard error.
 22→    pub stderr: String,
 23→
 24→    /// Execution duration.
 25→    pub duration: Duration,
 26→
 27→    /// Whether command succeeded (exit code 0).
 28→    pub success: bool,
 29→}
 30→
 31→impl CommandResult {
 32→    /// Create a success result.
 33→    pub fn success(stdout: String, stderr: String, duration: Duration) -> Self {
 34→        Self {
 35→            exit_code: Some(0),
 36→            stdout,
 37→            stderr,
 38→            duration,
 39→            success: true,
 40→        }
 41→    }
 42→
 43→    /// Create a failure result.
 44→    pub fn failure(
 45→        exit_code: Option<i32>,
 46→        stdout: String,
 47→        stderr: String,
 48→        duration: Duration,
 49→    ) -> Self {
 50→        Self {
 51→            exit_code,
 52→            stdout,
 53→            stderr,
 54→            duration,
 55→            success: false,
 56→        }
 57→    }
 58→}
 59→
 60→/// Options for command execution.
 61→#[derive(Debug, Clone, Default)]
 62→pub struct CommandOptions {
 63→    /// Working directory.
 64→    pub cwd: Option<std::path::PathBuf>,
 65→
 66→    /// Environment variables (merged with system env).
 67→    pub env: HashMap<String, String>,
 68→
 69→    /// Capture stdout (if false, inherits from parent).
 70→    pub capture_stdout: bool,
 71→
 72→    /// Capture stderr (if false, inherits from parent).
 73→    pub capture_stderr: bool,
 74→
 75→    /// Timeout in seconds (None = no timeout).
 76→    pub timeout: Option<u64>,
 77→}
 78→
 79→/// Output line from command execution.
 80→#[derive(Debug, Clone)]
 81→pub enum OutputLine {
 82→    Stdout(String),
 83→    Stderr(String),
 84→}
 85→
 86→/// Callback for streaming output.
 87→pub type OutputCallback = Box<dyn Fn(OutputLine) + Send>;
 88→
 89→/// Execute a shell command.
 90→pub fn execute(command: &str, options: &CommandOptions) -> Result<CommandResult> {
 91→    let start = Instant::now();
 92→
 93→    let shell = detect_shell();
 94→    let shell_flag = shell_flag(&shell);
 95→
 96→    let mut cmd = Command::new(&shell);
 97→    cmd.arg(shell_flag);
 98→    cmd.arg(command);
 99→
100→    // Set working directory
101→    if let Some(cwd) = &options.cwd {
102→        cmd.current_dir(cwd);
103→    }
104→
105→    // Set environment
106→    for (key, value) in &options.env {
107→        cmd.env(key, value);
108→    }
109→
110→    // Configure stdio
111→    if options.capture_stdout {
112→        cmd.stdout(Stdio::piped());
113→    } else {
114→        cmd.stdout(Stdio::inherit());
115→    }
116→
117→    if options.capture_stderr {
118→        cmd.stderr(Stdio::piped());
119→    } else {
120→        cmd.stderr(Stdio::inherit());
121→    }
122→
123→    // Execute
124→    let output = cmd.output().map_err(|_| BivvyError::CommandFailed {
125→        command: command.to_string(),
126→        code: None,
127→    })?;
128→
129→    let duration = start.elapsed();
130→
131→    let stdout = if options.capture_stdout {
132→        String::from_utf8_lossy(&output.stdout).to_string()
133→    } else {
134→        String::new()
135→    };
136→
137→    let stderr = if options.capture_stderr {
138→        String::from_utf8_lossy(&output.stderr).to_string()
139→    } else {
140→        String::new()
141→    };
142→
143→    if output.status.success() {
144→        Ok(CommandResult::success(stdout, stderr, duration))
145→    } else {
146→        Ok(CommandResult::failure(
147→            output.status.code(),
148→            stdout,
149→            stderr,
150→            duration,
151→        ))
152→    }
153→}
154→
155→/// Execute a command and return success/failure.
156→pub fn execute_check(command: &str, cwd: Option<&Path>) -> bool {
157→    let options = CommandOptions {
158→        cwd: cwd.map(|p| p.to_path_buf()),
159→        capture_stdout: true,
160→        capture_stderr: true,
161→        ..Default::default()
162→    };
163→
164→    execute(command, &options)
165→        .map(|r| r.success)
166→        .unwrap_or(false)
167→}
168→
169→/// Execute a command with streaming output.
170→pub fn execute_streaming(
171→    command: &str,
172→    options: &CommandOptions,
173→    callback: OutputCallback,
174→) -> Result<CommandResult> {
175→    let start = Instant::now();
176→
177→    let shell = detect_shell();
178→    let shell_flag = shell_flag(&shell);
179→
180→    let mut cmd = Command::new(&shell);
181→    cmd.arg(shell_flag);
182→    cmd.arg(command);
183→
184→    if let Some(cwd) = &options.cwd {
185→        cmd.current_dir(cwd);
186→    }
187→
188→    for (key, value) in &options.env {
189→        cmd.env(key, value);
190→    }
191→
192→    cmd.stdout(Stdio::piped());
193→    cmd.stderr(Stdio::piped());
194→
195→    let mut child = cmd.spawn().map_err(|_| BivvyError::CommandFailed {
196→        command: command.to_string(),
197→        code: None,
198→    })?;
199→
200→    let stdout = child.stdout.take().unwrap();
201→    let stderr = child.stderr.take().unwrap();
202→
203→    let (tx, rx) = mpsc::channel();
204→    let tx_stdout = tx.clone();
205→    let tx_stderr = tx;
206→
207→    // Spawn threads to read stdout and stderr
208→    let stdout_handle = thread::spawn(move || {
209→        let reader = BufReader::new(stdout);
210→        let mut output = String::new();
211→        for line in reader.lines().map_while(std::result::Result::ok) {
212→            output.push_str(&line);
213→            output.push('\n');
214→            let _ = tx_stdout.send(OutputLine::Stdout(line));
215→        }
216→        output
217→    });
218→
219→    let stderr_handle = thread::spawn(move || {
220→        let reader = BufReader::new(stderr);
221→        let mut output = String::new();
222→        for line in reader.lines().map_while(std::result::Result::ok) {
223→            output.push_str(&line);
224→            output.push('\n');
225→            let _ = tx_stderr.send(OutputLine::Stderr(line));
226→        }
227→        output
228→    });
229→
230→    // Process output through callback
231→    for line in rx {
232→        callback(line);
233→    }
234→
235→    let stdout_output = stdout_handle.join().unwrap_or_default();
236→    let stderr_output = stderr_handle.join().unwrap_or_default();
237→
238→    let status = child.wait().map_err(|_| BivvyError::CommandFailed {
239→        command: command.to_string(),
240→        code: None,
241→    })?;
242→
243→    let duration = start.elapsed();
244→
245→    if status.success() {
246→        Ok(CommandResult::success(
247→            stdout_output,
248→            stderr_output,
249→            duration,
250→        ))
251→    } else {
252→        Ok(CommandResult::failure(
253→            status.code(),
254→            stdout_output,
255→            stderr_output,
256→            duration,
257→        ))
258→    }
259→}
260→
261→/// Execute a command and collect output without streaming.
262→pub fn execute_quiet(command: &str, cwd: Option<&Path>) -> Result<CommandResult> {
263→    let options = CommandOptions {
264→        cwd: cwd.map(|p| p.to_path_buf()),
265→        capture_stdout: true,
266→        capture_stderr: true,
267→        ..Default::default()
268→    };
269→    execute(command, &options)
270→}
271→
272→/// Detect the current shell.
273→fn detect_shell() -> String {
274→    if cfg!(target_os = "windows") {
275→        std::env::var("COMSPEC").unwrap_or_else(|_| "cmd.exe".to_string())
276→    } else {
277→        std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".to_string())
278→    }
279→}
280→
281→/// Get the flag to pass commands to the shell.
282→///
283→/// Uses `-lic` (interactive login shell) on Unix so that the user's
284→/// full shell environment is available. Tools like mise, asdf, nvm,
285→/// and rbenv are typically activated in `.zshrc`/`.bashrc` (interactive)
286→/// or `.zprofile`/`.bash_profile` (login). Without `-lic`, these tools
287→/// aren't in PATH and step commands fail with "command not found".
288→///
289→/// In CI environments, uses `-lc` (login, non-interactive) to avoid
290→/// `bash: cannot set terminal process group` errors caused by `-i`
291→/// trying to set up job control without a TTY.
292→fn shell_flag(_shell: &str) -> &'static str {
293→    if cfg!(target_os = "windows") {
294→        "/C"
295→    } else if super::is_ci() {
296→        "-lc"
297→    } else {
298→        "-lic"
299→    }
300→}
