    fn recovery_abort_stops_workflow() {
        // Step fails, user picks Abort. No further steps execute.
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("should_not_run.txt");

        let config: BivvyConfig = serde_yaml::from_str(
